def _centro(d):
    """Centro aproximado do município (média dos vértices do maior anel), para o rótulo no mapa."""
    import re
    aneis = re.findall(r"M([^Z]+)Z", d)
    xy = max(([float(v) for v in re.findall(r"-?\d+(?:\.\d+)?", a)] for a in aneis), key=len)
    return [round(sum(xy[0::2]) / len(xy[0::2]), 1), round(sum(xy[1::2]) / len(xy[1::2]), 1)]


for _m in MAPA["municipios"].values():
    _m["c"] = _centro(_m["d"])


def ponto(lat, lon):
    p = MAPA["proj"]
    return (round((lon * p["k"] - p["mnx"]) * p["S"], 1), round((-lat - p["mny"]) * p["S"], 1))
